/* ------------------------------------------------------------------ */
/*  Reveal-on-scroll primitive                                         */
/*  Each section/card mounts hidden, then animates in the moment it    */
/*  crosses into the viewport (IntersectionObserver, fires once).      */
/* ------------------------------------------------------------------ */
function useInView(threshold = 0.15) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.unobserve(el);
        }
      },
      { threshold, rootMargin: "0px 0px -8% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold]);

  return [ref, inView];
}

function Reveal({ children, delay = 0, y = 24, className = "" }) {
  const [ref, inView] = useInView();
  return (
    <div
      ref={ref}
      style={{ transitionDelay: inView ? `${delay}ms` : "0ms" }}
      className={`transition-all duration-700 ease-out will-change-transform ${
        inView ? "opacity-100 translate-y-0" : "opacity-0"
      } ${className}`}
      // translate before reveal
    >
      <div
        style={{ transform: inView ? "none" : `translateY(${y}px)` }}
        className="transition-transform duration-700 ease-out"
      >
        {children}
      </div>
    </div>
  );
}

