/* ------------------------------------------------------------------ */
/*  Clients strip                                                       */
/* ------------------------------------------------------------------ */
function Clients() {
  const logosPerPage = 6;
  const [currentPage, setCurrentPage] = useState(0);
  const pageCount = Math.ceil(CLIENTS.length / logosPerPage);
  const visibleClients = CLIENTS.slice(
    currentPage * logosPerPage,
    (currentPage + 1) * logosPerPage,
  );

  useEffect(() => {
    const autoAdvance = setInterval(() => {
      setCurrentPage((page) => (page + 1) % pageCount);
    }, 5000);

    return () => clearInterval(autoAdvance);
  }, [currentPage, pageCount]);

  const showPrevious = () => {
    setCurrentPage((page) => (page - 1 + pageCount) % pageCount);
  };

  const showNext = () => {
    setCurrentPage((page) => (page + 1) % pageCount);
  };

  return (
    <section className="bg-slate-50/60 py-16">
      <Reveal>
        <h2 className="text-center text-lg font-semibold text-slate-500">
          Khách hàng của chúng tôi
        </h2>
      </Reveal>
      <Reveal delay={100}>
        <div className="mx-auto mt-8 max-w-5xl rounded-3xl border border-slate-200 bg-white px-5 py-8 shadow-sm md:px-10">
          <div
            key={currentPage}
            className="clients-page-enter grid min-h-32 grid-cols-2 items-center gap-6 sm:grid-cols-3 md:grid-cols-6 md:gap-8"
          >
            {visibleClients.map((client) => (
              <div
                key={client.name}
                className="group flex h-16 flex-col items-center justify-center gap-2 text-center transition-all duration-300 hover:scale-105"
              >
                <img
                  src={client.image}
                  alt={`Logo ${client.name}`}
                  className="h-9 max-w-[8rem] object-contain grayscale opacity-60 transition-all duration-300 group-hover:grayscale-0 group-hover:opacity-100"
                  onError={(event) => {
                    event.currentTarget.style.display = "none";
                  }}
                />
                <span className="text-xs font-black tracking-tight text-slate-400 transition-colors group-hover:text-[#2170e4]">
                  {client.name}
                </span>
              </div>
            ))}
          </div>

          <div className="mt-8 flex items-center justify-center gap-4">
            <button
              type="button"
              onClick={showPrevious}
              aria-label="Xem nhóm logo trước"
              className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 text-slate-500 transition-all hover:border-[#2170e4] hover:bg-[#2170e4] hover:text-white"
            >
              <ChevronLeft size={18} />
            </button>
            <div
              className="flex items-center gap-1.5"
              aria-label={`Nhóm logo ${currentPage + 1} trên ${pageCount}`}
            >
              {Array.from({ length: pageCount }, (_, page) => (
                <button
                  key={page}
                  type="button"
                  onClick={() => setCurrentPage(page)}
                  aria-label={`Xem nhóm logo ${page + 1}`}
                  className={`h-2 rounded-full transition-all duration-300 ${
                    page === currentPage
                      ? "w-6 bg-[#2170e4]"
                      : "w-2 bg-slate-300 hover:bg-blue-300"
                  }`}
                />
              ))}
            </div>
            <button
              type="button"
              onClick={showNext}
              aria-label="Xem nhóm logo tiếp theo"
              className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 text-slate-500 transition-all hover:border-[#2170e4] hover:bg-[#2170e4] hover:text-white"
            >
              <ChevronRight size={18} />
            </button>
          </div>
        </div>
      </Reveal>
    </section>
  );
}

